CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY,title TEXT NOT NULL,host_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'setup',round INTEGER NOT NULL DEFAULT 1,current_ship_id TEXT,revision INTEGER NOT NULL DEFAULT 0,last_op_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships(game_id TEXT NOT NULL REFERENCES games(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL DEFAULT 'player',PRIMARY KEY(game_id,user_id));
CREATE TABLE IF NOT EXISTS invitations(token_hash TEXT PRIMARY KEY,game_id TEXT NOT NULL REFERENCES games(id),created_by TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,redeemed_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ships(id TEXT PRIMARY KEY,game_id TEXT NOT NULL REFERENCES games(id),owner_id TEXT NOT NULL REFERENCES users(id),label TEXT NOT NULL,range_band INTEGER NOT NULL DEFAULT 2,stats_json TEXT NOT NULL,remaining INTEGER NOT NULL,initiative INTEGER NOT NULL DEFAULT 0,actions_left INTEGER NOT NULL DEFAULT 0,handling_lost INTEGER NOT NULL DEFAULT 0,attack_penalty INTEGER NOT NULL DEFAULT 0,dodge_bonus INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,game_id TEXT NOT NULL REFERENCES games(id),round INTEGER NOT NULL,ship_id TEXT NOT NULL REFERENCES ships(id),player_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_ships_game ON ships(game_id,initiative DESC);
CREATE INDEX IF NOT EXISTS idx_actions_game ON actions(game_id,round,created_at);